window.modules["pages/course/course.js"]=function(require,module,exports){

const {page,api,confirm,toast}=require('../../services/page');
const {toCourseCard,recordView}=require('../../domain/view-models');const {money}=require('../../domain/money');
Page(page({data:{id:'',course:null,packs:[],records:[],cursor:null},onLoad(o){this.setData({id:o.id});},async onShow(){await this.load();},async load(){const s=await api.call('dashboard.get');const c=s.courses.find(c=>c.id===this.data.id);if(!c)throw new Error('课程不存在或已失去访问权限');const r=await api.call('record.list',{courseId:c.id});this.setData({course:toCourseCard(c),packs:s.packs.filter(p=>p.courseId===c.id).reverse().map(p=>({...p,paidText:money(p.paidCents),totalText:p.totalUnits/2,remainingText:p.remainingUnits/2})),records:r.items.map(r=>recordView(r,s.courses)),cursor:r.nextCursor});},async more(){await this.run(async()=>{const r=await api.call('record.list',{courseId:this.data.id,cursor:this.data.cursor});this.setData({records:this.data.records.concat(r.items.map(r=>recordView(r))),cursor:r.nextCursor});});},async cancelRecord(e){if(!await confirm('撤销这条记录？','将退回原课包中的课时和金额，并保留撤销历史。'))return;await this.run(async()=>{await api.call('record.cancel',{id:e.currentTarget.dataset.id});toast('已撤销');await this.load();});},async cancelPack(e){if(!await confirm('撤销这笔续费？','只能撤销没有有效扣课记录的课包，历史仍然保留。'))return;await this.run(async()=>{await api.call('pack.cancel',{id:e.currentTarget.dataset.id});toast('已撤销续费');await this.load();});},async archive(){if(!await confirm(this.data.course.archived?'恢复课程？':'归档课程？','历史账目会保留，归档课程暂停新增打卡与续费。'))return;await this.run(async()=>{await api.call(this.data.course.archived?'course.restore':'course.archive',{id:this.data.id});await this.load();});}}));

};
