window.modules["pages/course-form/course-form.js"]=function(require,module,exports){

const {page,api,toast}=require('../../services/page');
Page(page({data:{id:'',name:'',institution:'',children:[],childIndex:0,color:'mint',icon:'music',leaveDeduct:false,threshold:'3',schedule:[],weekdayIndex:5,time:'17:00',weekdays:['周一','周二','周三','周四','周五','周六','周日'],colors:[{id:'mint',name:'薄荷绿'},{id:'blue',name:'天空蓝'},{id:'peach',name:'蜜桃粉'},{id:'lavender',name:'香芋紫'},{id:'butter',name:'奶油黄'}],icons:[{id:'music',name:'♫ 音乐'},{id:'swim',name:'≈ 游泳'},{id:'art',name:'✿ 美术'},{id:'book',name:'Aa 阅读'},{id:'dance',name:'♧ 舞蹈'},{id:'ball',name:'◎ 运动'}]},onLoad(o){this.setData({id:o.id||''});},async onShow(){const s=await api.call('dashboard.get');this.setData({children:s.children});if(this.data.id&&!this.loaded){const c=s.courses.find(c=>c.id===this.data.id);if(!c)throw new Error('课程不存在');this.setData({...c,threshold:String(c.thresholdUnits/2),childIndex:Math.max(0,s.children.findIndex(x=>x.id===c.childId))});this.loaded=true;}},choose(e){this.setData({[e.currentTarget.dataset.field]:e.currentTarget.dataset.id});},addSlot(){const weekday=(Number(this.data.weekdayIndex)+1)%7;const s={weekday,time:this.data.time};if(this.data.schedule.some(x=>x.weekday===s.weekday&&x.time===s.time))return;this.setData({schedule:this.data.schedule.concat(s)});},removeSlot(e){this.setData({schedule:this.data.schedule.filter((_,i)=>i!==Number(e.currentTarget.dataset.index))});},async save(){await this.run(async()=>{const child=this.data.children[Number(this.data.childIndex)];if(!child)throw new Error('请先添加孩子');const {parseUnits}=require('../../domain/money');const c=await api.call('course.save',{id:this.data.id||undefined,name:this.data.name,institution:this.data.institution,childId:child.id,color:this.data.color,icon:this.data.icon,leaveDeduct:this.data.leaveDeduct,thresholdUnits:parseUnits(this.data.threshold),schedule:this.data.schedule});toast('课程已保存');wx.redirectTo({url:'/pages/course/course?id='+c.id});});}}));

};
window.templates["pages/course-form/course-form"]="<view class=\"page\"><view class=\"eyebrow\">A NEW LITTLE ADVENTURE</view><view class=\"title top-space\">{{id ? '编辑课程' : '添一门喜欢的课'}}</view><view class=\"subtitle\">让兴趣有迹可循，让成长从容一点。</view><view wx:if=\"{{error}}\" class=\"error\">{{error}}</view><view wx:if=\"{{!children.length}}\" class=\"empty section\"><view>先给孩子建一个小档案吧</view><button class=\"primary top-space\" bindtap=\"go\" data-url=\"/pages/child-form/child-form\">添加孩子</button></view><block wx:if=\"{{children.length}}\"><view class=\"field\"><text class=\"label\">属于哪位宝贝</text><picker range=\"{{children}}\" range-key=\"name\" value=\"{{childIndex}}\" bindchange=\"input\" data-field=\"childIndex\"><view class=\"picker\">{{children[childIndex].name}} ▾</view></picker></view><view class=\"field\"><text class=\"label\">课程名称</text><input placeholder=\"例如：钢琴启蒙\" value=\"{{name}}\" bindinput=\"input\" data-field=\"name\" maxlength=\"40\"/></view><view class=\"field\"><text class=\"label\">机构名称 · 选填</text><input placeholder=\"在哪里上课？\" value=\"{{institution}}\" bindinput=\"input\" data-field=\"institution\" maxlength=\"60\"/></view><view class=\"field\"><text class=\"label\">选一个课程图标</text><view class=\"chip-row\"><view wx:for=\"{{icons}}\" wx:key=\"id\" class=\"chip {{icon===item.id?'active':''}}\" bindtap=\"choose\" data-field=\"icon\" data-id=\"{{item.id}}\">{{item.name}}</view></view></view><view class=\"field\"><text class=\"label\">给课程一点颜色</text><view class=\"chip-row\"><view wx:for=\"{{colors}}\" wx:key=\"id\" class=\"color-chip {{item.id}} {{color===item.id?'selected':''}}\" bindtap=\"choose\" data-field=\"color\" data-id=\"{{item.id}}\">{{item.name}} {{color===item.id?'✓':''}}</view></view></view><view class=\"panel section\"><view class=\"subheading\">固定上课时间 · 选填</view><view class=\"help\">仅用于日历和下次上课提示，不会自动扣课。</view><view class=\"row top-space\"><picker class=\"grow\" range=\"{{weekdays}}\" value=\"{{weekdayIndex}}\" bindchange=\"input\" data-field=\"weekdayIndex\"><view class=\"picker\">{{weekdays[weekdayIndex]}} ▾</view></picker><picker class=\"grow\" mode=\"time\" value=\"{{time}}\" bindchange=\"input\" data-field=\"time\"><view class=\"picker\">{{time}} ▾</view></picker><button class=\"plain\" bindtap=\"addSlot\">添加</button></view><view wx:for=\"{{schedule}}\" wx:key=\"index\" class=\"row top-space\"><text>每{{weekdays[(item.weekday+6)%7]}} {{item.time}}</text><text class=\"delete\" bindtap=\"removeSlot\" data-index=\"{{index}}\">移除</text></view></view><view class=\"field switch-line\"><view><view class=\"label\">请假也扣课时</view><view class=\"help\">按机构的实际规则设置</view></view><switch checked=\"{{leaveDeduct}}\" color=\"#376f58\" bindchange=\"toggle\" data-field=\"leaveDeduct\"/></view><view class=\"field\"><text class=\"label\">剩余多少节时提示续费</text><input type=\"digit\" value=\"{{threshold}}\" bindinput=\"input\" data-field=\"threshold\"/></view><view class=\"help\">保存课程后可添加首个课包，记录购课金额和节数。</view><button class=\"primary section\" bindtap=\"save\" loading=\"{{busy}}\" disabled=\"{{busy}}\">保存课程</button></block></view>";
