window.modules["pages/home/home.js"]=function(require,module,exports){

const {page,api,toast,confirm}=require('../../services/page');
const {toCourseCard}=require('../../domain/view-models');
const {chinaToday,slotsForDate}=require('../../domain/dates');
Page(page({data:{snapshot:null,courses:[],children:[],selectedChild:'',activeCount:0,monthCount:0,lowCount:0,todayText:'',lastId:''},
async onShow(){await this.load();},async load(){const snapshot=await api.call('dashboard.get').catch(e=>{if(e.code==='NO_FAMILY')return null;throw e;});if(!snapshot){this.setData({snapshot:null,courses:[]});return;}this.snapshot=snapshot;this.filter();},
filter(){const s=this.snapshot;const child=this.data.selectedChild;const courses=s.courses.filter(c=>!c.archived&&(!child||c.childId===child)).map(toCourseCard);const today=chinaToday();this.setData({snapshot:s,children:s.children,courses,activeCount:courses.length,monthCount:courses.reduce((n,c)=>n+((s.monthCounts||{})[c.id]||0),0),lowCount:courses.filter(c=>c.low).length,expiryCount:courses.filter(c=>c.expiresSoonOn).length,todayText:today.slice(5).replace('-','月')+'日'});},
selectChild(e){this.setData({selectedChild:e.currentTarget.dataset.id});this.filter();},
async checkIn(e){const id=e.currentTarget.dataset.id,c=this.data.courses.find(c=>c.id===id);const slots=slotsForDate(c.schedule,chinaToday());if(slots.length>1){wx.navigateTo({url:'/pages/record-form/record-form?id='+id});return;}await this.run(async()=>{const r=await api.call('record.create',{courseId:id,date:chinaToday(),slotId:slots.length?slots[0].id:'default',units:2,kind:'attended'});this.setData({lastId:r.id});toast(r.duplicate?'这节课已经记录过啦':'已记录，继续成长');await this.load();});},
async undo(){await this.run(async()=>{await api.call('record.cancel',{id:this.data.lastId});this.setData({lastId:''});toast('已撤销并退回课时');await this.load();});}
}));

};
window.templates["pages/home/home"]="<view class=\"page home-page\">\n<view wx:if=\"{{demo}}\" class=\"demo\"><text>演示体验 · 数据仅保存在当前设备</text><text>DEMO</text></view>\n<view class=\"hero\"><view><view class=\"eyebrow\">LITTLE STEPS, BIG DREAMS</view><view class=\"title\">每一小步，<text>\n</text>都值得记住。</view><view class=\"subtitle\">把琐碎交给课课记，把陪伴留给孩子。</view></view><view class=\"hero-flower\"><view class=\"petal p1\"></view><view class=\"petal p2\"></view><view class=\"petal p3\"></view><view class=\"petal p4\"></view><view class=\"flower-center\">☺</view><view class=\"stem\"></view><view class=\"leaf\"></view></view></view>\n<view wx:if=\"{{loading}}\" class=\"loading\">正在翻开课程小账本…</view><view wx:if=\"{{error}}\" class=\"error\" bindtap=\"retry\">{{error}} · 点击重试</view>\n<block wx:if=\"{{snapshot}}\">\n<view class=\"chip-row\"><view class=\"chip {{selectedChild === '' ? 'active' : ''}}\" bindtap=\"selectChild\" data-id=\"\">全部宝贝</view><view wx:for=\"{{children}}\" wx:key=\"id\" class=\"chip {{selectedChild === item.id ? 'active' : ''}}\" bindtap=\"selectChild\" data-id=\"{{item.id}}\">{{item.name}}</view><view class=\"chip add-child\" bindtap=\"go\" data-url=\"/pages/child-form/child-form\">＋</view></view>\n<view class=\"overview\"><view><view class=\"metric-number\">{{activeCount}}<text> 门</text></view><view class=\"muted\">在学课程</view></view><view class=\"overview-divider\"></view><view><view class=\"metric-number\">{{monthCount}}<text> 次</text></view><view class=\"muted\">本月已上课</view></view><view class=\"overview-art\">一点一滴<text>\n</text><text>慢慢长大 ↗</text></view></view>\n<view wx:if=\"{{lowCount}}\" class=\"reminder\"><text>◷ {{lowCount}} 门课程的课时快用完啦</text><text class=\"small\">记得安排续费</text></view>\n<view wx:if=\"{{expiryCount}}\" class=\"reminder\"><text>◷ {{expiryCount}} 门课程的课包将在14天内到期</text><text class=\"small\">记得安排上课</text></view><view wx:if=\"{{lastId}}\" class=\"undo row\"><text>✓ 上课已记录</text><text class=\"link\" bindtap=\"undo\">撤销这次打卡</text></view>\n<view class=\"row section\"><view class=\"section-title\">我的课程 <text class=\"muted\">{{courses.length}}</text></view><view class=\"link\" bindtap=\"go\" data-url=\"/pages/course-form/course-form\">＋ 添加课程</view></view>\n<view wx:if=\"{{!courses.length}}\" class=\"empty section\"><view class=\"empty-icon\">✿</view><view class=\"subheading\">从第一门喜欢的课开始</view><view class=\"subtitle\">添加孩子和课程，就能轻松记录每一次成长。</view><button class=\"primary top-space\" bindtap=\"go\" data-url=\"/pages/course-form/course-form\">添加第一门课程</button></view>\n<view class=\"course-list\">\n<view wx:for=\"{{courses}}\" wx:key=\"id\" class=\"course-card {{item.color}}\">\n<view class=\"row\" bindtap=\"go\" data-url=\"{{'/pages/course/course?id='+item.id}}\"><view class=\"course-icon\">{{item.iconText}}</view><view class=\"grow\"><view class=\"course-name\">{{item.name}}</view><view class=\"course-meta\">{{item.childName}} · {{item.institution || '记录每一次进步'}}</view></view><text class=\"chevron\">↗</text></view>\n<view class=\"course-balance row\" bindtap=\"go\" data-url=\"{{'/pages/course/course?id='+item.id}}\"><view><text class=\"balance-number\">{{item.remainingText}}</text><text class=\"balance-unit\"> 节剩余</text></view><text wx:if=\"{{item.low}}\" class=\"low-tag\">快用完啦</text><text wx:else class=\"course-meta\">已用 {{item.usedText}} / {{item.totalText}} 节</text></view>\n<view class=\"progress-track\"><view class=\"progress-fill\" style=\"width:{{item.percent}}%\"></view></view>\n<view wx:if=\"{{item.expiresSoonOn}}\" class=\"help\">课包即将到期：{{item.expiresSoonOn}}</view><view class=\"next-lesson\">◷ 下次：{{item.nextText}}</view>\n<view class=\"course-actions\"><button class=\"check-button\" bindtap=\"checkIn\" data-id=\"{{item.id}}\" disabled=\"{{busy || !item.canCheckIn}}\">✓ 上课打卡</button><button class=\"leave-button\" bindtap=\"go\" data-url=\"{{'/pages/record-form/record-form?id='+item.id+'&kind=leave'}}\">请假</button></view>\n</view></view>\n<view class=\"footer-note\">用心陪伴，每一步都有回响 🌱</view></block>\n<view wx:if=\"{{!snapshot && !loading && !error}}\" class=\"empty section\"><view class=\"empty-icon\">⌂</view><view class=\"section-title\">一起，记录成长</view><view class=\"subtitle\">创建家庭或接受家人的邀请，共享一本课程账。</view><button class=\"primary top-space\" bindtap=\"go\" data-url=\"/pages/family/family\">创建或加入家庭</button></view>\n</view>";
window.styles["pages/home/home"]="\n.hero{position:relative;padding:8rpx 0 20rpx;min-height:240rpx}.hero .title{margin-top:16rpx;font-size:49rpx;max-width:490rpx}.hero .subtitle{font-size:23rpx;margin-top:20rpx;max-width:475rpx}.hero-flower{position:absolute;right:3rpx;top:70rpx;width:104rpx;height:145rpx;transform:rotate(12deg)}.petal{position:absolute;width:52rpx;height:52rpx;border-radius:50%;background:#efd9ac}.p1{left:26rpx;top:0}.p2{left:0;top:28rpx}.p3{left:52rpx;top:28rpx}.p4{left:26rpx;top:54rpx}.flower-center{position:absolute;left:32rpx;top:33rpx;width:40rpx;height:40rpx;border-radius:50%;background:#d8b16f;color:#8c6a3e;font-size:29rpx;line-height:40rpx;text-align:center;z-index:2}.stem{position:absolute;width:4rpx;height:56rpx;background:#8aab80;left:51rpx;top:91rpx}.leaf{position:absolute;top:111rpx;left:52rpx;width:35rpx;height:19rpx;border-radius:0 30rpx 0 30rpx;background:#b9cba1;transform:rotate(-30deg)}.overview{background:#f0f3e7;border:1rpx solid #e5eadc;border-radius:30rpx;padding:28rpx 30rpx;display:flex;align-items:center;gap:30rpx}.metric-number{font-size:48rpx;font-weight:650;line-height:1.3}.metric-number text{font-size:23rpx;font-weight:400}.overview-divider{width:1rpx;height:55rpx;background:#dce3d3}.overview-art{margin-left:auto;text-align:right;font-size:22rpx;color:#99a589;line-height:1.9}.overview-art text{color:#607a54}.reminder{display:flex;justify-content:space-between;gap:10rpx;font-size:23rpx;color:#9a7d48;background:#faf3de;border-radius:18rpx;padding:18rpx 22rpx;margin-top:20rpx}.undo{padding:22rpx 4rpx;color:#3c785b;font-size:24rpx}.course-list{display:flex;flex-direction:column;gap:26rpx;margin-top:24rpx}.course-card{border-radius:34rpx;padding:28rpx 30rpx 26rpx}.course-icon{width:78rpx;height:78rpx;border-radius:24rpx;background:#ffffff90;display:flex;align-items:center;justify-content:center;font-size:39rpx;color:#496b59;flex-shrink:0}.course-name{font-size:32rpx;font-weight:650}.course-meta{font-size:22rpx;color:#7c8a80;margin-top:4rpx;word-break:break-all}.chevron{font-size:33rpx;color:#738b78}.course-balance{margin-top:25rpx;align-items:baseline}.balance-number{font-size:54rpx;font-weight:650;letter-spacing:-1rpx}.balance-unit{font-size:24rpx;color:#667d6e}.low-tag{font-size:21rpx;color:#9c7844;background:#fff8e7;padding:5rpx 14rpx;border-radius:14rpx}.progress-track{height:8rpx;border-radius:9rpx;background:#ffffff95;margin-top:13rpx;overflow:hidden}.progress-fill{height:100%;background:#93b69f;border-radius:9rpx}.blue .progress-fill{background:#95b8ce}.peach .progress-fill{background:#d7af9b}.lavender .progress-fill{background:#b7a6ce}.next-lesson{font-size:22rpx;color:#7c897f;margin:16rpx 0 22rpx}.course-actions{display:flex;gap:16rpx}.check-button{flex:1;background:#ffffffd6;color:#3f6b50;min-height:80rpx;padding:20rpx}.leave-button{width:146rpx;background:#ffffff55;color:#6e8074;min-height:80rpx;padding:20rpx}.add-child{padding-left:24rpx;padding-right:24rpx}\n";
window.modules["pages/profile/profile.js"]=function(require,module,exports){
const {page,api}=require('../../services/page');
Page(page({data:{family:{children:[]},archived:[]},async onShow(){const family=await api.call('bootstrap'),s=await api.call('dashboard.get');this.setData({family,archived:s.courses.filter(c=>c.archived)});},settings(){window.personalSettings.open();},exportData(){window.personalSettings.export();},help(){wx.showModal({title:'安心记录每一小步',content:'先添加孩子、课程和课包。打卡会自动扣课，请假按课程设置处理；误操作可撤销。每次修改先保存到手机，再尝试备份 GitHub。请以顶部“已备份到 GitHub”为准；关闭页面后不能保证后台上传。',showCancel:false});}}));

};
window.templates["pages/profile/profile"]="<view class=\"page\"><view class=\"eyebrow\">A LITTLE BOOK OF GROWTH</view><view class=\"title top-space\">把成长，好好收藏。</view><view class=\"subtitle\">一个人也能轻松记好，每一次用心陪伴。</view><view wx:if=\"{{error}}\" class=\"error\" bindtap=\"retry\">{{error}}</view><view class=\"panel section\" bindtap=\"settings\"><view class=\"row\"><view class=\"avatar\">↥</view><view class=\"grow\"><view class=\"section-title\">我的数据与备份</view><view class=\"muted\">手机保存 · GitHub 私有备份</view></view><text class=\"link\">设置 ›</text></view></view><view class=\"row section\"><view class=\"section-title\">家里的小宝贝</view><text class=\"link\" bindtap=\"go\" data-url=\"/pages/child-form/child-form\">＋ 添加</text></view><view class=\"panel top-space\"><view wx:if=\"{{!family.children.length}}\" class=\"muted\">添加昵称和头像，就可以开始记录了。</view><view wx:for=\"{{family.children}}\" wx:key=\"id\" class=\"menu row\" bindtap=\"go\" data-url=\"{{'/pages/child-form/child-form?id='+item.id}}\"><view class=\"row start\"><view class=\"avatar\">{{item.avatar==='sun'?'☀':item.avatar==='star'?'☆':item.avatar==='flower'?'✿':'♧'}}</view><text class=\"subheading\">{{item.name}}</text></view><text class=\"muted\">编辑 ›</text></view></view><view class=\"panel section\"><view class=\"menu row\" bindtap=\"exportData\"><text>↗ 导出完整备份</text><text class=\"muted\">JSON ›</text></view><view class=\"menu row\" bindtap=\"settings\"><text>↻ 从备份恢复</text><text class=\"muted\">›</text></view><view class=\"menu row\" bindtap=\"help\"><text>♡ 使用小贴士</text><text class=\"muted\">›</text></view></view><block wx:if=\"{{archived.length}}\"><view class=\"section-title section\">已归档课程</view><view class=\"panel top-space\"><view wx:for=\"{{archived}}\" wx:key=\"id\" class=\"menu row\" bindtap=\"go\" data-url=\"{{'/pages/course/course?id='+item.id}}\"><text>{{item.name}}</text><text class=\"muted\">查看 / 恢复 ›</text></view></view></block><view class=\"footer-note\">课课记 · 单人网页版<text>\n</text>把琐碎记下来，把时间留给陪伴。</view></view>\n";
