window.modules["pages/record-form/record-form.js"]=function(require,module,exports){

const {page,api,toast,confirm}=require('../../services/page');const {chinaToday,slotsForDate}=require('../../domain/dates');const {parseUnits}=require('../../domain/money');
Page(page({data:{id:'',course:null,date:chinaToday(),today:chinaToday(),kind:'attended',units:'1',note:'',slots:[],slotIndex:0,extra:false,time:'',extraId:''},onLoad(o){this.setData({id:o.id,kind:o.kind||'attended',date:o.date||chinaToday(),extraId:'extra-'+Date.now().toString(36)});const pending=api.pending().find(x=>x.action==='record.create'&&x.payload.courseId===o.id&&(!o.date||x.payload.date===o.date));if(pending){this.pendingRequest=pending;const p=pending.payload;this.setData({date:p.date,kind:p.kind,units:String(p.units/2),note:p.note||'',time:p.time||'',extra:p.slotId.startsWith('extra-'),extraId:p.slotId,restoredSlot:p.slotId,restored:true});}},async onShow(){const s=await api.call('dashboard.get');const c=s.courses.find(c=>c.id===this.data.id);if(!c)throw new Error('课程不存在');this.setData({course:c});this.refreshSlots();},refreshSlots(){const slots=slotsForDate(this.data.course.schedule,this.data.date).map(s=>({...s,label:s.time+' 固定课表'}));this.setData({slots,slotIndex:Math.max(0,slots.findIndex(s=>s.id===this.data.restoredSlot))});},changeDate(e){this.setData({date:e.detail.value});this.refreshSlots();},chooseKind(e){this.setData({kind:e.currentTarget.dataset.kind});},async save(){await this.run(async()=>{if(this.pendingRequest){const r=this.pendingRequest;await api.call(r.action,r.payload,r.operationId);toast('记录已确认');wx.navigateBack();return;}if(this.data.kind==='leave'&&this.data.course.leaveDeduct&&!await confirm('这次请假将扣课','将按机构设置扣除 '+this.data.units+' 节，是否记录？'))return;const slot=this.data.slots[Number(this.data.slotIndex)];await api.call('record.create',{courseId:this.data.id,date:this.data.date,kind:this.data.kind,units:parseUnits(this.data.units),slotId:this.data.extra?this.data.extraId:slot?slot.id:'default',time:this.data.time||(slot?slot.time:''),note:this.data.note});toast('已经记好啦');wx.navigateBack();});}}));

};
